import React from 'react';
import { motion } from 'framer-motion';
import siteData from '../data/siteData.json';

const Services = () => {
  const { servicesPage } = siteData;

  return (
    <div className="min-h-screen">
      {/* Hero Section */}
      <section className="relative h-[60vh] flex items-center justify-center">
        <div 
          className="absolute inset-0 bg-cover bg-center bg-no-repeat"
          style={{ backgroundImage: 'url(/images/services-bg.jpg)' }}
        >
          <div className="absolute inset-0 bg-black/50" />
        </div>
        <motion.div 
          className="relative text-center text-white z-10"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
        >
          <h1 className="text-5xl font-bold mb-4">{servicesPage.hero.title}</h1>
          <p className="text-xl">{servicesPage.hero.subtitle}</p>
        </motion.div>
      </section>

      {/* Services List */}
      <section className="py-16 px-4 md:px-8">
        <div className="max-w-6xl mx-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {servicesPage.services.map((service) => (
              <motion.div
                key={service.id}
                className="bg-white rounded-lg shadow-lg overflow-hidden"
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8 }}
                viewport={{ once: true }}
              >
                <div className="h-48 overflow-hidden">
                  <img
                    src={service.image}
                    alt={service.name}
                    className="w-full h-full object-cover"
                  />
                </div>
                <div className="p-6">
                  <h3 className="text-xl font-semibold mb-2">{service.name}</h3>
                  <p className="text-gray-600 mb-4">{service.description}</p>
                  <div className="flex justify-between items-center">
                    <span className="text-2xl font-bold text-primary">{service.price}€</span>
                    <span className="text-gray-500">{service.duration}</span>
                  </div>
                  <ul className="mt-4 space-y-2">
                    {service.includes.map((item, index) => (
                      <li key={index} className="flex items-center text-gray-600">
                        <span className="mr-2">✓</span>
                        {item}
                      </li>
                    ))}
                  </ul>
                  <button className="mt-6 w-full bg-primary text-white py-2 px-4 rounded-lg hover:bg-primary-dark transition-colors">
                    Réserver
                  </button>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Additional Info */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-4xl mx-auto px-4 md:px-8">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            viewport={{ once: true }}
            className="text-center"
          >
            <h2 className="text-3xl font-bold mb-6">{servicesPage.additionalInfo.title}</h2>
            <p className="text-lg text-gray-700 leading-relaxed">{servicesPage.additionalInfo.content}</p>
          </motion.div>
        </div>
      </section>
    </div>
  );
};

export default Services;
